import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On a round table, {n} labeled seats are arranged in a circle. A seating pattern is a binary sequence (b_1, b_2, ..., b_{n}) with b_i in {0,1}, where adjacency is taken cyclically (i.e., pairs (b_i, b_{i+1}) for i=1,...,{n}-1 and also (b_{n}, b_{1})). Among all such binary sequences, consider those that simultaneously satisfy the following:\n- exactly {k} entries are 1;\n- exactly {r} reverse orders occur (adjacent pair 1 followed by 0);\n- exactly {s} forward orders occur (adjacent pair 0 followed by 1);\n- every run of consecutive 1s has length at most {max_ones_run};\n- every run of consecutive 0s has length at most {max_zeros_run}.\nPositions are labeled, so rotations are considered different. How many such sequences exist?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate parameters ensuring non-trivial, feasible instances.
# We enforce r=s (a necessary cyclic condition), and run-length bounds that don't trivialize.
for _ in range(1000):
    n = rng.randint(14, 22)
    L = rng.randint(2, 5)  # max_ones_run
    Z = rng.randint(2, 5)  # max_zeros_run
    max_r = min(6, n // 4)
    if max_r < 2:
        continue
    r = rng.randint(2, max_r)
    s = r  # cyclic necessity
    # Choose k so that compositions into r positive parts with bounds exist for both ones and zeros.
    low_k = max(r, n - r * Z)
    high_k = min(n - r, r * L)
    if low_k > high_k:
        continue
    k = rng.randint(low_k, high_k)
    # Avoid extremely tight cases occasionally to keep variety
    if rng.random() < 0.2 and high_k - low_k >= 2:
        k = rng.randint(low_k + 1, high_k - 1)
    return {
        'n': n,
        'k': k,
        'r': r,
        's': s,
        'max_ones_run': L,
        'max_zeros_run': Z
    }
# Fallback deterministic instance if random attempts fail (unlikely)
return {
    'n': 18,
    'k': 9,
    'r': 3,
    's': 3,
    'max_ones_run': 3,
    'max_zeros_run': 3
}

    def verifier(assign):
# Validate and compute the answer via dynamic programming with cyclic adjacency and run-length constraints.
# Return (True, answer) for valid instances; (False, None) if the assignment violates domain constraints.
n = assign.get('n')
k = assign.get('k')
r = assign.get('r')
s = assign.get('s')
L = assign.get('max_ones_run')
Z = assign.get('max_zeros_run')
# Basic checks
if not all(isinstance(x, int) for x in [n, k, r, s, L, Z]):
    # invalid types
    return False, None  # invalid types
if not (1 <= n <= 60):
    return False, None  # n out of reasonable bounds
if not (0 <= k <= n):
    return False, None  # invalid k
if not (0 <= r <= n and 0 <= s <= n):
    return False, None  # invalid transition counts
if not (1 <= L <= n and 1 <= Z <= n):
    return False, None  # invalid run limits
# Enforce non-trivial hardness conditions
if r < 2 or s < 2:
    return False, None  # too easy (requires at least 2 transitions of each type)
if L < 2 or Z < 2:
    return False, None  # trivializes runs
# Feasibility checks derived from cyclic structure:
# In any cyclic binary sequence, the number of 10 transitions equals the number of 01 transitions.
if r != s:
    # No sequence can satisfy this; instance considered invalid for this family.
    return False, None
# With r=s>0, there are exactly r runs of 1s and r runs of 0s; hence k >= r, n-k >= r.
if k < r or (n - k) < r:
    return False, None
# Each run length is at least 1, at most the respective cap; feasibility requires k in [r, r*L] and n-k in [r, r*Z].
if not (r <= k <= r * L):
    return False, None
if not (r <= (n - k) <= r * Z):
    return False, None

# Dynamic programming over labeled positions with cyclic adjacency.
# State: (ones_used, c10, c01, prev_bit, run_len, init_len, switched)
# init_len = length of the initial run of the starting bit; switched = whether we've left the starting run.

def count_sequences(n, k, r, s, L, Z):
    total = 0
    for start in (0, 1):
        # Initialize after placing b0 = start
        ones_used = start
        prev = start
        run_len = 1
        init_len = 1
        switched = False
        dp = {(ones_used, 0, 0, prev, run_len, init_len, switched): 1}
        # Place positions 1..n-1
        for pos in range(1, n):
            new_dp = {}
            for (ou, c10, c01, pv, rl, il, sw), cnt in dp.items():
                # Try next bit
                for nxt in (0, 1):
                    new_ou = ou + (1 if nxt == 1 else 0)
                    if new_ou > k:
                        continue
                    new_c10 = c10 + (1 if pv == 1 and nxt == 0 else 0)
                    new_c01 = c01 + (1 if pv == 0 and nxt == 1 else 0)
                    if new_c10 > r or new_c01 > s:
                        continue
                    if nxt == pv:
                        new_rl = rl + 1
                        cap = L if nxt == 1 else Z
                        if new_rl > cap:
                            continue
                        new_sw = sw
                        # If we have not yet left the starting run and still matching start, extend init_len
                        if not sw and nxt == start:
                            new_il = il + 1
                        else:
                            new_il = il
                    else:
                        new_rl = 1
                        new_sw = sw or (pv == start)
                        new_il = il
                        # new_rl = 1 always satisfies cap
                    key = (new_ou, new_c10, new_c01, nxt, new_rl, new_il, new_sw)
                    new_dp[key] = new_dp.get(key, 0) + cnt
            dp = new_dp
        # Finalize wrap adjacency and merged run check
        for (ou, c10, c01, last, rl, il, sw), cnt in dp.items():
            if ou != k:
                continue
            c10_final = c10 + (1 if (last == 1 and start == 0) else 0)
            c01_final = c01 + (1 if (last == 0 and start == 1) else 0)
            if c10_final != r or c01_final != s:
                continue
            # Check merged run across wrap when last == start
            if last == start:
                # If never switched, the entire circle is a single run of length n.
                combined_len = (rl + il) if sw else n
                cap = L if start == 1 else Z
                if combined_len > cap:
                    continue
            total += cnt
    return total

answer = count_sequences(n, k, r, s, L, Z)
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

